#!/usr/bin/env python3
from pwn import *

# Set up logging
context.log_level = 'debug'

def connect_to_service():
    """Create connection to the service"""
    try:
        return remote('crypto.chal.csaw.io', 8040)
    except Exception as e:
        log.error(f"Connection failed: {str(e)}")
        return None

def send_and_receive(conn, data):
    """Send data to service and receive response"""
    try:
        # Send our data
        conn.sendline(data)

        # Receive and parse response
        response = conn.recvline().strip()
        enc_response = conn.recvline().strip()

        return response, enc_response
    except Exception as e:
        log.error(f"Communication error: {str(e)}")
        return None, None

def test_service():
    """Test the service with a basic payload"""
    conn = connect_to_service()
    if not conn:
        return

    # Create test payload - 20 'A's
    test_payload = 'A' * 20

    try:
        # Send payload and get response
        print(f"\nSending payload: {test_payload}")
        response, enc_response = send_and_receive(conn, test_payload)

        if response and enc_response:
            print("\nReceived response:")
            print(f"Message 1: {response}")
            print(f"Message 2: {enc_response}")

            # If response is hex, try to show it in a cleaner format
            try:
                enc_bytes = bytes.fromhex(enc_response.decode())
                print("\nHexdump of encrypted data:")
                print(hexdump(enc_bytes))
            except:
                pass

    finally:
        conn.close()

if __name__ == "__main__":
    test_service()

