import string
import statistics
import time

# Configure the connection
HOST = 'crypto.chal.csaw.io'
PORT = 8040  # We'll stick to one port for consistency
context.log_level = 'error'  # Reduce noise

def try_connect():
    """Try to establish connection"""
    try:
        conn = remote(HOST, PORT, timeout=5)
        return conn
    except Exception:
        return None

def get_response_length(response):
    """Extract the length from the server response"""
    try:
        # Response format has the encrypted data in the middle line
        lines = response.split(b'\n')
        if len(lines) > 1:
            encrypted = eval(lines[1])  # The encrypted data is in the second line
            return len(encrypted)
    except:
        pass
    return None

def test_guess(known_prefix, guess, num_attempts=3):
    """Test a guess by making multiple requests and returning average encrypted length"""
    lengths = []
    for _ in range(num_attempts):
        conn = try_connect()
        if not conn:
            continue

        try:
            # Receive initial prompt
            conn.recvline()

            # Construct test string
            test_str = (known_prefix + guess) * 3 + "a" * 20

            # Send test string
            conn.sendline(test_str.encode())
            response = conn.recvuntil(b"service\n", timeout=2)

            length = get_response_length(response)
            if length is not None:
                lengths.append(length)

        except Exception as e:
            pass
        finally:
            try:
                conn.close()
            except:
                pass

        time.sleep(0.5)  # Increased delay between attempts

    if not lengths:
        print(f"Warning: No successful attempts for guess '{guess}'")
        return float('inf')

    # Return average length
    return statistics.mean(lengths)

def find_next_char(known_prefix):
    """Find the next character by testing all possibilities"""
    charset = string.ascii_lowercase + '_'
    best_len = float('inf')
    best_char = None
    results = []

    print(f"\nTesting characters for prefix '{known_prefix}':")

    for c in charset:
        avg_len = test_guess(known_prefix, c)
        if avg_len != float('inf'):
            results.append((c, avg_len))
            print(f"Char '{c}': avg_length = {avg_len:.2f}")

            if avg_len < best_len:
                best_len = avg_len
                best_char = c

    if not best_char:
        raise Exception("Could not determine next character")

    return best_char, best_len

def main():
    known = ""
    prev_len = float('inf')
    last_chars = []

    print("Starting compression oracle attack...")

    while True:
        try:
            next_char, length = find_next_char(known)
            known += next_char
            print(f"\nFound character: {next_char}")
            print(f"Current key: {known}")

            # Keep track of last few characters and their lengths
            last_chars.append((next_char, length))
            if len(last_chars) > 3:
                last_chars.pop(0)

            # Check for potential end conditions
            if len(last_chars) == 3:
                # If the last three lengths are very similar
                lengths = [l for _, l in last_chars]
                if max(lengths) - min(lengths) < 0.5:
                    print("\nDetected stable lengths, potential end of key!")
                    break

            # Break if the key gets unreasonably long
            if len(known) > 30:
                print("\nReached maximum length, stopping...")
                break

            prev_len = length

        except Exception as e:
            print(f"Error occurred: {e}")
            break

    print(f"\nFinal result: {known}")

if __name__ == "__main__":
    main()

