        conn.sendline(test_str.encode())
        response = conn.recvline(timeout=0.5)
        conn.close()

        if b"b'" in response:
            encrypted = eval(response.strip())
            return len(encrypted)
    except:
        try:
            conn.close()
        except:
            pass
